# Read driverStandings.csv and find Alex Yoong's races with round < 20
yoong_races = []
with open('csv/driverStandings.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['driverId'] == '62':
            raceId = row['raceId']
            if raceId in races and races[raceId]['round'] < 20:
                yoong_races.append({'race_name': races[raceId]['name'], 'round': races[raceId]['round']})

# Sort by round
yoong_races.sort(key=lambda x: x['round'])

for r in yoong_races:
    print(r['race_name'], r['round'])
print(f"\nTotal races: {len(yoong_races)}")

