import csv

# Read races.csv
races = {}
with open('csv/races.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        races[row['raceId']] = {'name': row['name'], 'round': int(row['round'])}

# Read driverStandings.csv and find Alex Yoong's races with round < 20
yoong_races = set()
with open('csv/driverStandings.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['driverId'] == '62':
            raceId = row['raceId']
            if raceId in races and races[raceId]['round'] < 20:
                yoong_races.add(races[raceId]['name'])

# Sort by round (need to re-query for ordering)
yoong_races_list = []
with open('csv/driverStandings.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['driverId'] == '62':
            raceId = row['raceId']
            if raceId in races and races[raceId]['round'] < 20:
                yoong_races_list.append(races[raceId]['name'])

# Get unique races in order of round
seen = set()
unique_races = []
with open('csv/driverStandings.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['driverId'] == '62':
            raceId = row['raceId']
            if raceId in races and races[raceId]['round'] < 20:
                race_name = races[raceId]['name']
                if race_name not in seen:
                    seen.add(race_name)
                    unique_races.append(race_name)

print("Unique races where Alex Yoong participated with round < 20:")
for r in unique_races:
    print(r)

